mapper.select:
SELECT `mr`.`id`, `mr`.`msg_scene_code`, `mr`.`msg_scene_name`, `mr`.`msg_content`, `mr`.`msg_tmp_id`, `mr`.`msg_params`, `mr`.`msg_type`, `mr`.`application_code`, `mr`.`application_name`, `mr`.`business_type`, `mr`.`business_id`, `mr`.`business_principal`, `mr`.`channel_code`, `mr`.`manufacturer_code`, `mr`.`send_time`, `mr`.`effective_days`, `mr`.`expiration_time`, `mr`.`url`, `mrt`.`has_read`, `mr`.`tenant`, `mr`.`deleted`, `mr`.`create_by`, `mr`.`creator_id`, `mr`.`creator_type`, `mr`.`create_time`, `mr`.`update_by`, `mr`.`updater_id`, `mr`.`updater_type`, `mr`.`update_time` FROM `msg_record` `mr` INNER JOIN `msg_record_target` `mrt` on `mr`.`id` = `mrt`.`msg_record_id` INNER JOIN ( SELECT DISTINCT msg_record_id FROM msg_record_terminal WHERE terminal = #{terminal} ) mrt_sub ON mr.id = mrt_sub.msg_record_id
mrt.`user_id` = #{userId}
and `mrt`.`send_status` = #{param.sendStatus}
and `mr`.`msg_content` = #{param.keyword}
and `mr`.`channel_code` = #{param.channelType} and `mrt`.`channel_code` = #{param.channelType}
and `mr`.`business_type` = #{param.businessType}
and `mr`.`msg_type` = #{param.msgType}
and `mr`.`application_code` = #{param.applicationCode}
and (`mrt`.`has_read` = #{param.hasRead} or `mrt`.`has_read` is null)
and `mr`.`send_time` >= #{param.period.begin}
and `mr`.`send_time` <= #{param.period.end}
and
( 1=1
and `mr`.`application_code` = #{group.appCode}
and `mr`.`msg_type` = #{group.msgType}
and `mr`.`msg_scene_code` = #{group.sceneCode}
)
and
( 1=1
and `mr`.`application_code` != #{group.appCode}
and `mr`.`msg_type` != #{group.msgType} or mr.msg_type is NULL
and `mr`.`msg_scene_code` != #{group.sceneCode}
)
order by `mrt`.`has_read` ASC, `mrt`.`create_time` DESC

SELECT distinct `mr`.`id`, `mr`.`msg_scene_code`, `mr`.`msg_scene_name`, `mr`.`msg_content`, `mr`.`msg_tmp_id`, `mr`.`msg_params`, `mr`.`msg_type`, `mr`.`application_code`, `mr`.`application_name`, `mr`.`business_type`, `mr`.`business_id`, `mr`.`business_principal`, `mr`.`channel_code`, `mr`.`manufacturer_code`, `mr`.`send_time`, `mr`.`effective_days`, `mr`.`expiration_time`, `mr`.`url`, `mrt`.`has_read`, `mr`.`tenant`, `mr`.`deleted`, `mr`.`create_by`, `mr`.`creator_id`, `mr`.`creator_type`, `mr`.`create_time`, `mr`.`update_by`, `mr`.`updater_id`, `mr`.`updater_type`, `mr`.`update_time` FROM `msg_record` `mr` INNER JOIN `msg_record_target` `mrt` on `mr`.`id` = `mrt`.`msg_record_id` INNER JOIN `msg_record_terminal` `mrtm` on `mr`.`id` = `mrtm`.`msg_record_id`
`mr`.`tenant` = #{param.tenant}
and `mrtm`.`terminal` = #{terminal}
and `mr`.`msg_content` = #{param.keyword}
and `mr`.`channel_code` = #{param.channelType} and `mrt`.`channel_code` = #{param.channelType}
and `mr`.`business_type` = #{param.businessType}
and `mr`.`msg_type` = #{param.msgType}
and `mr`.`application_code` = #{param.applicationCode}
and (`mrt`.`has_read` = #{param.hasRead} or `mrt`.`has_read` is null)
and `mr`.`send_time` >= #{param.period.begin}
and `mr`.`send_time` <= #{param.period.end}
and
( 1=1
and `mr`.`application_code` = #{group.appCode}
and `mr`.`msg_type` = #{group.msgType}
and `mr`.`msg_scene_code` = #{group.sceneCode}
)
and
( 1=1
and `mr`.`application_code` != #{group.appCode}
and `mr`.`msg_type` != #{group.msgType} or mr.msg_type is NULL
and `mr`.`msg_scene_code` != #{group.sceneCode}
)
order by `mrt`.`has_read` ASC, `mr`.`send_time` DESC

SELECT `mr`.`msg_type`, COUNT(`mr`.`id`) as `total` FROM `msg_record` `mr` INNER JOIN `msg_record_target` `mrt` on `mrt`.`msg_record_id` = `mr`.`id` INNER JOIN `msg_record_terminal` `mrtm` on `mr`.`id` = `mrtm`.`msg_record_id`
`mrt`.`user_id` = #{userId} and mrt.`has_read` = false and `mr`.`channel_type` = #{channelType} and `mrtm`.`terminal` = #{terminal}
GROUP BY `mr`.`msg_type`

SELECT `t3`.`application_code`, `t3`.`application_name`, `t3`.`total`, `t3`.`last_time` FROM ( SELECT `mr`.`application_code`, `mr`.`application_name`, COALESCE ( sum( IF ( `mrt`.`has_read` = FALSE OR `mrt`.`has_read` IS NULL, 1, 0 )), 0 ) AS `total`, MAX( `mr`.`create_time` ) AS `last_time` FROM `msg_record` `mr` INNER JOIN `msg_record_target` `mrt` ON `mrt`.`msg_record_id` = `mr`.`id`
`mrt`.`user_id` = #{userId} and `mr`.`channel_code` = #{channelType} and `mrt`.`channel_code` = #{channelType}
and
( 1=1
and `mr`.`application_code` != #{group.appCode}
and `mr`.`msg_type` != #{group.msgType} or mr.msg_type is NULL
and `mr`.`msg_scene_code` != #{group.sceneCode}
)
GROUP BY `mr`.`application_code`,`mr`.`application_name` ) `t3` ORDER BY `t3`.`last_time` DESC;

SELECT `t3`.`application_code`, `t3`.`application_name` FROM ( SELECT `mr`.`application_code`, `mr`.`application_name`, MAX( `mr`.`create_time` ) AS `last_time` FROM `msg_record` `mr` INNER JOIN `msg_record_target` `mrt` ON `mrt`.`msg_record_id` = `mr`.`id` INNER JOIN `msg_record_terminal` `mrtm` on `mr`.`id` = `mrtm`.`msg_record_id`
`mrt`.`user_id` = #{userId} and `mr`.`channel_code` = #{channelType} and `mrtm`.`terminal` = #{terminal}
GROUP BY `mr`.`application_code`,`mr`.`application_name` ) `t3` ORDER BY `t3`.`last_time` DESC

SELECT
COALESCE ( sum( IF ( `mrt`.`has_read` = false OR `mrt`.`has_read` IS NULL, 1, 0 )), 0 ) AS `unReadMsgCount`
FROM
`msg_record` `mr`
INNER JOIN `msg_record_target` `mrt` ON `mrt`.`msg_record_id` = `mr`.`id`

    `mrt`.`user_id` = #{userId}
    and `mr`.`channel_code` = #{channelType}
    and `mrt`.`channel_code` = #{channelType}

        and

            (
            1=1

                and `mr`.`application_code` = #{group.appCode}


                and `mr`.`msg_type` = #{group.msgType}


                and `mr`.`msg_scene_code` = #{group.sceneCode}

            )

SELECT
`mr`.*
FROM
`msg_record` `mr`
INNER JOIN `msg_record_target` `mrt` ON `mrt`.`msg_record_id` = `mr`.`id`

    `mrt`.`user_id` = #{userId}
    and `mr`.`channel_code` = #{channelType}
    and `mrt`.`channel_code` = #{channelType}

        and

            (
            1=1

                and `mr`.`application_code` = #{group.appCode}


                and `mr`.`msg_type` = #{group.msgType}


                and `mr`.`msg_scene_code` = #{group.sceneCode}

            )



ORDER BY `mr`.`create_time` desc
LIMIT 0,1

SELECT
`mr`.*
FROM
`msg_record` `mr`
INNER JOIN `msg_record_target` `mrt` ON `mrt`.`msg_record_id` = `mr`.`id`

    `mrt`.`user_id` = #{userId}
    and `mr`.`channel_code` = #{channelType}
    and `mrt`.`channel_code` = #{channelType}
    and `mr`.`application_code` = #{applicationCode}

        and



                    (
                    1=1

                        and `mr`.`application_code` != #{group.appCode}


                        and (`mr`.`msg_type` != #{group.msgType} or `mr`.`msg_type` is null or `mr`.msg_type = '')


                        and `mr`.`msg_scene_code` != #{group.sceneCode}

                    )





ORDER BY `mr`.`create_time` desc
LIMIT 0,1
